import subprocess
from pathlib import Path

wt=Path("/Users/steventran/.do_again/stall-dedupe-20261007")
branch="feat/stall-issue-dedupe-20261007"
expected="1df7744078b5ae0c7f97897c0e105be4f5e185e6"

def run(args,check=True):
    return subprocess.run(args,cwd=wt,text=True,capture_output=True,check=check)

if run(["git","rev-parse","HEAD"]).stdout.strip()!=expected:
    raise SystemExit("unexpected head")
if run(["git","branch","--show-current"]).stdout.strip()!=branch:
    raise SystemExit("unexpected branch")
if run(["git","status","--porcelain=v1"]).stdout.strip():
    raise SystemExit("worktree not clean")

p=run(["git","push","-u","origin",branch],check=False)
print(p.stdout); print(p.stderr)
print("push_rc="+str(p.returncode))
if p.returncode:
    raise SystemExit(p.returncode)

remote=run(["git","ls-remote","origin",f"refs/heads/{branch}"]).stdout.strip()
print("remote_ref="+remote)
if expected not in remote:
    raise SystemExit("remote ref mismatch")
print("status_after="+repr(run(["git","status","--porcelain=v1"]).stdout))
